-- PREPARED ONLY; source-reviewed at da87399c317d89f85ca8076a6dc1643c4c8995cc.
-- Root executes only against staging project kubdiqdhqbhwmqfditeg, never production.
-- FIRST copy run-e-manual-default-ledger.md's ...0015 entry to the durable ledger.
-- FIRST visibly decline ordinary clear 01a0a44c-796b-775c-ae39-3d2b0d513585.
-- Stop submissions. This transaction inserts exactly one labeled SQL fixture.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

DO $fixture$
DECLARE
 account_uuid constant uuid := '019f43e0-0000-7000-8000-000000000001';
 actor_uuid constant uuid := '019f43e0-0000-7000-8000-000000000002';
 auth_uuid constant uuid := 'ac02a2a9-98b7-4fdf-9957-560d387759e1';
 salon_uuid constant uuid := '019f43e0-0000-7000-8000-000000000011';
 cafe_uuid constant uuid := '019f43e0-0000-7000-8000-000000000012';
 manual_uuid constant uuid := '019f43e0-0000-7000-8000-000000000014';
 default_uuid constant uuid := '019f43e0-0000-7000-8000-000000000015';
 declined_uuid constant uuid := '01a0a44c-796b-775c-ae39-3d2b0d513585';
 declined_row public.agent_proposals%ROWTYPE;
BEGIN
 -- Preserve the existing lifecycle order: location, account, then proposal.
 PERFORM id FROM public.businesses
 WHERE id=cafe_uuid AND account_id=account_uuid AND name='Cafe'
   AND display_label='Cafe' AND owner_email='run-e-019f43e0@e2e.repworth.net'
   AND onboarded_by=actor_uuid AND archived_at IS NULL
   AND google_place_id IS NULL
 FOR NO KEY UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Exact synthetic Cafe guard failed'; END IF;

 PERFORM id FROM public.accounts
 WHERE id=account_uuid AND owner_user_id=actor_uuid
   AND display_name='Run E Synthetic Account'
   AND subscription_tier='autopilot' AND subscription_status='active'
   AND stripe_customer_id IS NULL AND stripe_subscription_id IS NULL
 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Exact synthetic account or Stripe-absence guard failed'; END IF;

 PERFORM u.id FROM public.users u JOIN auth.users a ON a.id::text=u.auth_id
 WHERE u.id=actor_uuid AND u.account_id=account_uuid AND u.role='owner'
   AND u.name='Run E Synthetic Owner' AND u.email='run-e-019f43e0@e2e.repworth.net'
   AND a.id=auth_uuid AND a.email=u.email
 FOR SHARE OF u,a;
 IF NOT FOUND THEN RAISE EXCEPTION 'Exact synthetic actor/Auth guard failed'; END IF;

 PERFORM id FROM public.businesses
 WHERE id=salon_uuid AND account_id=account_uuid AND name='Salon'
   AND display_label='Salon' AND owner_email='run-e-019f43e0@e2e.repworth.net'
   AND onboarded_by=actor_uuid AND archived_at IS NULL
   AND google_place_id IS NULL
 FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Exact synthetic Salon guard failed'; END IF;
 IF (SELECT count(*) FROM public.businesses WHERE account_id=account_uuid) <> 2
   OR EXISTS(SELECT 1 FROM public.google_connections c JOIN public.businesses b ON b.id=c.business_id WHERE b.account_id=account_uuid)
   OR EXISTS(SELECT 1 FROM public.zernio_connections c JOIN public.businesses b ON b.id=c.business_id WHERE b.account_id=account_uuid)
 THEN RAISE EXCEPTION 'Synthetic location inventory or Google/Zernio-absence guard failed'; END IF;

 SELECT * INTO STRICT declined_row FROM public.agent_proposals
 WHERE id=declined_uuid AND account_id=account_uuid
   AND location_id=cafe_uuid AND actor_user_id=actor_uuid
 FOR UPDATE;
 IF declined_row.operation IS DISTINCT FROM 'clear_location_override'
   OR declined_row.contract_version IS DISTINCT FROM 1
   OR declined_row.input IS DISTINCT FROM '{}'::jsonb
   OR declined_row.status IS DISTINCT FROM 'rejected'
   OR declined_row.decided_by_user_id IS DISTINCT FROM actor_uuid
   OR declined_row.failure_reason IS NOT NULL
   OR declined_row.applied_at IS NOT NULL OR declined_row.receipt IS NOT NULL
   OR declined_row.before->'rowExists' IS DISTINCT FROM 'true'::jsonb
   OR declined_row.before->'threshold' IS DISTINCT FROM 'null'::jsonb
   OR declined_row.before->'vetoWindowMinutes' IS DISTINCT FROM '30'::jsonb
   OR declined_row.before->'dailyAutoPostCap' IS DISTINCT FROM '2'::jsonb
   OR declined_row.after->'rowExists' IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION 'Blocked ordinary clear was not explicitly declined with the expected manual preview'; END IF;

 IF EXISTS(SELECT 1 FROM public.agent_turns WHERE account_id=account_uuid AND status IN ('accepted','running'))
   OR EXISTS(SELECT 1 FROM public.agent_proposals WHERE account_id=account_uuid AND status='pending')
 THEN RAISE EXCEPTION 'Stop submissions and settle every pending fixture proposal before setup'; END IF;

 PERFORM id FROM public.auto_approval_policies
 WHERE id=manual_uuid AND account_id=account_uuid AND location_id=cafe_uuid
   AND persona='reply' AND action_class='posting'
   AND auto_approve_min_star IS NULL AND veto_window_minutes=30 AND daily_auto_post_cap=2
   AND suspended_at IS NULL AND suspended_reason IS NULL
 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Exact unsuspended manual Cafe policy guard failed'; END IF;
 IF EXISTS(SELECT 1 FROM public.auto_approval_policies WHERE id=default_uuid)
   OR EXISTS(SELECT 1 FROM public.auto_approval_policies WHERE account_id=account_uuid AND location_id IS NULL)
   OR (SELECT count(*) FROM public.auto_approval_policies WHERE account_id=account_uuid) <> 1
 THEN RAISE EXCEPTION 'Expected account-default absence, sole manual policy, or fresh fixture UUID guard failed'; END IF;

 INSERT INTO public.auto_approval_policies
   (id,account_id,location_id,persona,action_class,auto_approve_min_star,veto_window_minutes,daily_auto_post_cap)
 VALUES (default_uuid,account_uuid,NULL,'reply','posting',NULL,30,2);
 -- No policy overwrite, synthetic receipt/audit/refusal, suspension edit, or flag change.
END $fixture$;

SELECT id,account_id,location_id,persona,action_class,auto_approve_min_star,
 veto_window_minutes,daily_auto_post_cap,suspended_at::text,suspended_reason,
 created_at::text,updated_at::text
FROM public.auto_approval_policies
WHERE account_id='019f43e0-0000-7000-8000-000000000001'
 AND id IN ('019f43e0-0000-7000-8000-000000000014','019f43e0-0000-7000-8000-000000000015')
ORDER BY location_id NULLS FIRST;
COMMIT;
